import pandas as pd


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # 1. Events delivered more than once are applied once (distinct by seq).
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Build initial per-order state dict from target_state.
    target_dict = {}
    for _, row in target_state.iterrows():
        oid = row["order_id"]
        target_dict[oid] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"],
        }

    # Group events per order, sorted by seq (the only trustworthy order).
    events_by_order = {}
    if len(cdc_events) > 0:
        for oid, grp in cdc_events.groupby("order_id"):
            events_by_order[oid] = grp.sort_values("seq")

    new_state = {}
    tombstones = []

    all_order_ids = set(target_dict.keys()) | set(events_by_order.keys())

    for oid in all_order_ids:
        orig = target_dict.get(oid)
        guard_seq = orig["last_seq"] if orig is not None else None
        state = dict(orig) if orig is not None else None

        tombstone_seq = None  # candidate deleted_seq if order ends up deleted

        events = events_by_order.get(oid)
        if events is not None:
            for _, ev in events.iterrows():
                seq = ev["seq"]

                # 2. Replay guard: skip events with seq <= row's ORIGINAL last_seq,
                # only if the order had a row in target_state.
                if guard_seq is not None and seq <= guard_seq:
                    continue

                op = ev["op"]
                status = ev["status"]
                amount = ev["amount"]

                if op in ("I", "U"):
                    if state is None:
                        # Created fresh: takes event amount as-is (NULL stays NULL).
                        state = {
                            "status": status,
                            "amount": amount,
                            "last_seq": seq,
                        }
                    else:
                        state["status"] = status
                        if op == "U" and pd.isna(amount):
                            # 'U' with NULL amount leaves existing amount unchanged.
                            pass
                        else:
                            state["amount"] = amount
                        state["last_seq"] = seq
                    tombstone_seq = None  # row exists now, clear any pending tombstone
                elif op == "D":
                    if state is not None:
                        state = None
                        tombstone_seq = seq
                    # 'D' for a currently-missing order does nothing,
                    # and does not change tombstone_seq.

        if state is not None:
            new_state[oid] = state
        else:
            if tombstone_seq is not None:
                tombstones.append({"order_id": oid, "deleted_seq": tombstone_seq})

    # Build new_state DataFrame.
    if new_state:
        new_state_rows = [
            {
                "order_id": oid,
                "status": s["status"],
                "amount": s["amount"],
                "last_seq": s["last_seq"],
            }
            for oid, s in new_state.items()
        ]
        new_state_df = pd.DataFrame(
            new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
        )
    else:
        new_state_df = pd.DataFrame(
            columns=["order_id", "status", "amount", "last_seq"]
        )

    if tombstones:
        tombstones_df = pd.DataFrame(
            tombstones, columns=["order_id", "deleted_seq"]
        )
    else:
        tombstones_df = pd.DataFrame(columns=["order_id", "deleted_seq"])

    return {"new_state": new_state_df, "tombstones": tombstones_df}
